use safe_bash_rust::commands::spreadsheet::{Spreadsheet, Style};
use std::sync::Arc;

const LIMIT: usize = 128 * 1024 * 1024;

#[test]
fn closedxml_original_alignment_fixture_retains_indent_through_json_and_xlsx() {
    // ClosedXML 057f5976c788d97e8eac86d1a528bd5411d9386e, MIT.
    // Unmodified Resource/Examples/Styles/StyleAlignment.xlsx, generated by
    // ClosedXML.Examples/Styles/StyleAlignment.cs (B3: Indent = 2).
    let book = Spreadsheet::import_xlsx(
        include_bytes!("fixtures/closedxml-style-alignment.xlsx"),
        LIMIT,
    )
    .unwrap();
    assert_eq!(book.display(0, 2, 1, LIMIT).unwrap(), "Indent = 2");
    let json = Spreadsheet::from_json(&book.to_json(), LIMIT).unwrap();
    let xlsx = Spreadsheet::import_xlsx(&book.export_xlsx(LIMIT).unwrap(), LIMIT).unwrap();
    for book in [&book, &json, &xlsx] {
        assert!(
            book.cell_style(0, 2, 1)
                .unwrap()
                .attributes
                .contains(&("Indent", "2".into()))
        );
    }
}

#[test]
fn closedxml_alignment_indent_boundary_cases_preserve_values() {
    // AlignmentTests.AlignmentApiSetters: 0, 1, 5, 255; retain style separately
    // from the value, including formula cells and non-left alignment.
    for indent in [0, 1, 5, 255] {
        for align in ["left", "right", "distributed"] {
            let mut book = Spreadsheet::new();
            book.edit(&[(0, 0, 0, "=6*7")], LIMIT).unwrap();
            book.sheets[0].cells.get_mut(&(0, 0)).unwrap().style = Some(Arc::new(Style {
                attributes: vec![("Indent", indent.to_string()), ("HAlign", align.into())],
                ..Style::default()
            }));
            let json = Spreadsheet::from_json(&book.to_json(), LIMIT).unwrap();
            let excel = Spreadsheet::import_xlsx(&json.export_xlsx(LIMIT).unwrap(), LIMIT).unwrap();
            assert_eq!(excel.display(0, 0, 0, LIMIT).unwrap(), "42");
            let style = excel.cell_style(0, 0, 0).unwrap();
            assert!(style.attributes.contains(&("Indent", indent.to_string())));
            assert!(style.attributes.contains(&("HAlign", align.into())));
        }
    }
}
